  border-color: var(--color-secondary);
  box-shadow: 0 0 0 3px rgba(0, 174, 239, 0.25);
  outline: none;
}
```

**6c. Lista de opciones (`#dropdown-list`) — OCULTA por defecto:**

```css
#dropdown-list {
  display: none;                        /* ESTADO BASE: oculto */
  position: absolute;
  top: calc(100% + var(--spacing-xs));
  left: 0;
  width: 100%;
