// ------------------------------------------------------------
// MIXIN 1: flex-center
// Aplicación futura en styles.css: .dropdown-item, .greeting-card
// ------------------------------------------------------------
@mixin flex-center($direction: row) {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-direction: $direction;
}


// ------------------------------------------------------------
// MIXIN 2: visually-hidden-toggle
// Aplicación futura en styles.css: #dropdown-list, #greeting-display
// Documenta el patrón de visibilidad del contrato de integración XP-13:
//   - Estado base (oculto):   display: none
//   - Estado activo (.is-active): display: $display-value
// El selector de activación sería "&.is-active" en el contexto del consumidor.
// ------------------------------------------------------------
@mixin visually-hidden-toggle($display-value: block) {
  // Estado base — elemento oculto por defecto
  display: none;

  // Estado activo — el selector "&.is-active" activaría esta regla:
  // display: $display-value;
}


// ------------------------------------------------------------
// MIXIN 3: responsive-breakpoint
// Breakpoints deben sincronizarse con las variables declaradas
// en css/_variables.scss cuando ese archivo sea activado.
// Uso: @include responsive-breakpoint(mobile) { ... reglas ... }
// ------------------------------------------------------------
@mixin responsive-breakpoint($breakpoint) {
  @if $breakpoint == mobile {
    @media (max-width: 480px) {
      @content;
    }
  } @else if $breakpoint == tablet {
    @media (max-width: 768px) {
      @content;
    }
  }
}


